// --- 3. Teachers API ---
app.get('/api/view-teachers', (req, res) => {
    db.query("SELECT t.*, u.username FROM teachers t JOIN users u ON t.user_id = u.id ORDER BY t.id DESC", (err, result) => res.json(result));
});

app.post('/api/add-teacher', (req, res) => {
    // මෙතනට subject එකත් එකතු කළා
    const { name, username, subject, qualifications, email, phone_number, address, password } = req.body;
    db.query("INSERT INTO users (username, password, role) VALUES (?, ?, 'teacher')", [username, password], (err, userResult) => {
        if (err) return res.json({ status: "Error", err });
        // Database එකට subject එක ලියනවා
        db.query("INSERT INTO teachers (user_id, name, subject, phone_number, email, qualifications, address) VALUES (?, ?, ?, ?, ?, ?, ?)", 
        [userResult.insertId, name, subject, phone_number, email, qualifications, address], (err2) => {
            if (err2) return res.json({ status: "Error", err: err2 });
            return res.json({ status: "Success" });
        });
    });
});

app.put('/api/edit-teacher/:id', (req, res) => {
    // Edit කරද්දිත් subject එක වෙනස් කරන්න පුළුවන් වෙන්න හැදුවා
    const { name, subject, phone_number, email, qualifications, address } = req.body;
    db.query(
        "UPDATE teachers SET name=?, subject=?, phone_number=?, email=?, qualifications=?, address=? WHERE id=?",
        [name, subject, phone_number, email, qualifications, address, req.params.id], 
        (err, result) => {
            if (err) return res.json({ status: "Error", error: err.sqlMessage });
            return res.json({ status: "Success" });
        }
    );
});

app.delete('/api/delete-teacher/:id', (req, res) => {
    db.query("DELETE FROM teachers WHERE id = ?", [req.params.id], (err, result) => {
        if (err) return res.json({ status: "Error" });
        return res.json({ status: "Success" });
    });
});
